#include <iostream>
using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 x, n;
    cin >> x >> n;

    int64 answer = 1;

    for (int64 p = 2; p * p <= x; ++p) {
        if (x % p != 0) continue;

        while (x % p == 0) x /= p;

        int64 exponent = 0;
        for (int64 value = n; value > 0;) {
            value /= p;
            exponent += value;
        }

        answer = answer * modPow(p, exponent) % MOD;
    }

    if (x > 1) {
        int64 exponent = 0;
        for (int64 value = n; value > 0;) {
            value /= x;
            exponent += value;
        }

        answer = answer * modPow(x, exponent) % MOD;
    }

    cout << answer << '\n';
    return 0;
}

